/**
 * @param {string} source
 * @param {string} target
 * @param {character[]} original
 * @param {character[]} changed
 * @param {number[]} cost
 * @return {number}
 */
var minimumCost = function(source, target, original, changed, cost) {
    let total = 0;

    let aCode = "a".charCodeAt(0);
    const map = Array(26).fill().map(() => Array(26).fill(Infinity));
    for (let i = 0; i < original.length; i++) {
        map[original[i].charCodeAt(0) - aCode][changed[i].charCodeAt(0) - aCode] = cost[i];
    }

    for (let k = 0; k < 26; k++) {
        for (let i = 0; i < 26; i++) {
            for (let j = 0; j < 26; j++) {
                if (map[i][j] > map[i][k] + map[k][j]) {
                    map[i][j] = map[i][k] + map[k][j];
                }
            }
        }
    }

    for (let i = 0; i < source.length; i++) {
        if (source[i] === target[i]) {
            continue;
        }

        const co = map[source.charCodeAt(i) - aCode][target.charCodeAt(i) - aCode];

        if (co === Infinity) {
            return -1;
        }

        total += co;
    }

    return total;
};

